mapper.update:
update ai_knowledge_base
set name = #{name},
    description = #{description}
where id = #{id}

update ai_knowledge_base kb
set document_count = (
        select count(1)
        from ai_knowledge_document doc
        where doc.knowledge_base_id = #{id}
          and doc.status = 'READY'
    ),
    chunk_count = (
        select coalesce(sum(doc.chunk_count), 0)
        from ai_knowledge_document doc
        where doc.knowledge_base_id = #{id}
          and doc.status = 'READY'
    )
where kb.id = #{id}
